DROP TABLE IF EXISTS `club_class_monthly_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `club_class_monthly_schedules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `class_id` int(11) NOT NULL,
  `trainer_id` int(11) NOT NULL,
  `month` tinyint(4) NOT NULL,
  `year` smallint(6) NOT NULL,
  `status` enum('draft','published','archived') NOT NULL DEFAULT 'draft',
  `published_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `club_class_monthly_schedules_class_id_trainer_id_month_year_key` (`class_id`,`trainer_id`,`month`,`year`),
  KEY `club_class_monthly_schedules_status_idx` (`status`),
  KEY `club_class_monthly_schedules_trainer_id_fkey` (`trainer_id`),
  CONSTRAINT `club_class_monthly_schedules_class_id_fkey` FOREIGN KEY (`class_id`) REFERENCES `club_lookups` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `club_class_monthly_schedules_trainer_id_fkey` FOREIGN KEY (`trainer_id`) REFERENCES `club_trainers` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
